// Generated by /ship review fix cycle 1 (Claude Opus 5.5) — 2026-10-18
// Value: protects=the /finance overview shows "Tạo yêu cầu thanh toán" only to viewers who can create a payment request (payments.create_request or payments.manage) AND hold students.view, the same gate as the list's "Tạo yêu cầu" and the /finance/payment-requests/new page, and links recent requests' student names to /students/{id} only with students.view;
// fails_when=the && students.view gate is dropped (the accountant gets a link to a page that answers "Không có quyền xem học viên") or the create codes stop counting;
// why_new=the overview had no test and step 14c aligned its gate with the list (review finding api-contract A1);
// seam=none (the permission reader and the overview loader are mocked at their module boundaries, the payment-request-route.test.tsx pattern); no_claim=the /new page's own guard and the overview's metrics or recent-request table
import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import FinanceOverviewPage from "@/app/(app)/finance/page";

const dependencies = vi.hoisted(() => ({
  getCachedDatabasePermissions: vi.fn(),
  getFinanceOverviewResult: vi.fn(),
}));

vi.mock("@/lib/permissions/database-permissions", () => ({
  getCachedDatabasePermissions: dependencies.getCachedDatabasePermissions,
}));
vi.mock("@/features/finance/data", () => ({
  getFinanceOverviewResult: dependencies.getFinanceOverviewResult,
}));

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

const overview = {
  cashflowSummary: { disbursementVnd: 0, receiptVnd: 0, refundVnd: 0 },
  recentCashflow: [],
  recentPaymentRequests: [],
  recentSepayTransactions: [],
  totalPaymentRequestsCount: 0,
};

async function renderWith(permissions: string[]) {
  dependencies.getCachedDatabasePermissions.mockResolvedValue({ ok: true, permissions });
  dependencies.getFinanceOverviewResult.mockResolvedValue({ data: overview, ok: true });
  render(await FinanceOverviewPage());
}

const createLink = () => screen.queryByRole("link", { name: "Tạo yêu cầu thanh toán" });

describe("/finance overview create link", () => {
  it.each([
    { label: "owner-like (create + students)", permissions: ["finance.view", "payments.create_request", "students.view"], visible: true },
    { label: "manage + students", permissions: ["finance.view", "payments.manage", "students.view"], visible: true },
    { label: "accountant (manage, no students.view)", permissions: ["finance.view", "payments.manage", "payments.view"], visible: false },
    { label: "create_request without students.view", permissions: ["finance.view", "payments.create_request"], visible: false },
    { label: "students.view without a create code", permissions: ["finance.view", "payments.view", "students.view"], visible: false },
  ])("$label → link visible: $visible", async ({ permissions, visible }) => {
    await renderWith(permissions);
    if (visible) {
      expect(createLink()).toHaveAttribute("href", "/finance/payment-requests/new");
    } else {
      expect(createLink()).not.toBeInTheDocument();
    }
    expect(screen.getByRole("heading", { name: "Học phí & Tài chính" })).toBeInTheDocument();
  });
});

const recentRequest = {
  bonusSessions: 0,
  calculatedUnitPriceVnd: 140000,
  createdAt: "2026-10-10T03:00:00.000Z",
  expectedAmountVnd: 1_400_000,
  guardianFullName: "Nguyễn Thị Mai",
  guardianPhone: "0900000000",
  id: "request-1",
  notes: null,
  paidAmountVnd: 0,
  paidAt: null,
  publicCode: "PAY-261010-000000000001",
  purchasedSessions: 10,
  status: "pending",
  studentFullName: "Nguyễn Minh An",
  studentId: "student-1",
  studentPublicCode: "HV001",
  topupType: "new",
  transferCode: "TTVC PAY-261010",
};

describe("/finance overview recent requests", () => {
  const profileLinks = () => screen.queryAllByRole("link").filter((link) => link.getAttribute("href")?.startsWith("/students/"));

  it("links student names only with students.view", async () => {
    dependencies.getCachedDatabasePermissions.mockResolvedValue({ ok: true, permissions: ["finance.view", "payments.manage", "payments.view"] });
    dependencies.getFinanceOverviewResult.mockResolvedValue({ data: { ...overview, recentPaymentRequests: [recentRequest] }, ok: true });
    render(await FinanceOverviewPage());
    expect(profileLinks()).toHaveLength(0);
    expect(screen.getAllByText("Nguyễn Minh An")).toHaveLength(2);
    cleanup();

    dependencies.getCachedDatabasePermissions.mockResolvedValue({ ok: true, permissions: ["finance.view", "payments.view", "students.view"] });
    render(await FinanceOverviewPage());
    expect(profileLinks()).toHaveLength(2);
    expect(profileLinks()[0]).toHaveAttribute("href", "/students/student-1");
  });
});
